begin;

create temporary table coding_question_seed (
  collection_slug text not null, slug text not null, title text not null,
  problem_statement text not null, difficulty text not null, topic_tags text[] not null,
  constraints jsonb not null, examples jsonb not null, starter_code_by_language jsonb not null,
  points integer not null, seed_order integer not null
) on commit drop;

insert into coding_question_seed
select r.collection_slug, r.slug, r.title, r.problem_statement, r.difficulty,
       array(select jsonb_array_elements_text(r.topic_tags)), r.constraints, r.examples,
       r.starter_code_by_language, r.points, r.seed_order
from jsonb_to_recordset($seed$[{"collection_slug":"python-programming","slug":"group-anagrams-canonical","title":"Group Anagrams","problem_statement":"Group words with the same lowercase English-letter multiset. Keep groups in order of first appearance in the input; sort words within each group.","difficulty":"Medium","topic_tags":["Dictionaries","Sorting"],"constraints":["1 <= len(words) <= 10000","Words contain lowercase English letters"],"examples":[{"input":"[eat, tea, tan, ate, nat, bat]","output":"[[\"ate\",\"eat\",\"tea\"],[\"nat\",\"tan\"],[\"bat\"]]"},{"input":"[abc,bca,cab]","output":"[[\"abc\",\"bca\",\"cab\"]]"}],"starter_code_by_language":{"Python":"def group_anagrams(words):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":150,"seed_order":1},{"collection_slug":"python-programming","slug":"stable-partition-pivot","title":"Stable Partition Around a Pivot","problem_statement":"Return values below pivot, then equal to pivot, then above pivot; preserve original order within all three groups.","difficulty":"Easy","topic_tags":["Lists","Stable Partition"],"constraints":["0 <= len(values) <= 100000","Values and pivot are integers"],"examples":[{"input":"values=[3,5,2,5,1,4], pivot=4","output":"[3,2,1,4,5,5]"},{"input":"values=[2,1,2], pivot=2","output":"[1,2,2]"}],"starter_code_by_language":{"Python":"def stable_partition(values, pivot):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":100,"seed_order":2},{"collection_slug":"python-programming","slug":"top-k-frequent-words","title":"Rank Frequent Words","problem_statement":"Return the k most frequent words by descending frequency; break ties by lexicographically ascending word.","difficulty":"Medium","topic_tags":["Dictionaries","Sorting"],"constraints":["1 <= len(words) <= 100000","1 <= k <= number of distinct words"],"examples":[{"input":"words=[i,love,leetcode,i,love,coding], k=2","output":"[\"i\",\"love\"]"},{"input":"words=[the,day,is,sunny,the,the,the,sunny,is,is], k=4","output":"[\"the\",\"is\",\"sunny\",\"day\"]"}],"starter_code_by_language":{"Python":"def top_k_frequent(words, k):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":150,"seed_order":3},{"collection_slug":"python-programming","slug":"longest-unique-substring-python","title":"Longest Distinct-Character Substring","problem_statement":"Return the length of the longest contiguous substring containing no repeated Unicode code points.","difficulty":"Medium","topic_tags":["Strings","Sliding Window"],"constraints":["0 <= len(text) <= 200000","text contains Unicode code points"],"examples":[{"input":"abcabcbb","output":"3"},{"input":"pwwkew","output":"3"}],"starter_code_by_language":{"Python":"def longest_unique_substring(text):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return 0"},"points":150,"seed_order":4},{"collection_slug":"python-programming","slug":"decode-nested-repetition","title":"Decode Nested Repetition","problem_statement":"Decode expressions count[content], where content may contain nested repetition expressions; counts are positive decimal integers.","difficulty":"Medium","topic_tags":["Stacks","Parsing"],"constraints":["Expression is valid and balanced","Decoded output length <= 100000","Literal characters are lowercase English letters"],"examples":[{"input":"3[a2[c]]","output":"accaccacc"},{"input":"2[ab]3[c]","output":"ababccc"}],"starter_code_by_language":{"Python":"def decode_repetition(expression):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return \"\""},"points":150,"seed_order":5},{"collection_slug":"python-programming","slug":"weighted-interval-scheduling","title":"Maximum Non-Overlapping Profit","problem_statement":"Choose non-overlapping jobs [start,end,profit] to maximize total profit; an end time equal to the next start is compatible.","difficulty":"Hard","topic_tags":["Dynamic Programming","Binary Search"],"constraints":["0 <= len(jobs) <= 100000","start < end","0 <= profit <= 1000000000"],"examples":[{"input":"[[1,3,50],[2,4,10],[3,5,40],[3,6,70]]","output":"120"},{"input":"[[1,2,5],[2,3,6]]","output":"11"}],"starter_code_by_language":{"Python":"def maximum_job_profit(jobs):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return 0"},"points":200,"seed_order":6},{"collection_slug":"python-programming","slug":"shortest-path-word-ladder","title":"Shortest Word Transformation","problem_statement":"Return the number of words in a shortest one-letter-at-a-time transformation from begin to end, requiring every changed word in the dictionary; return 0 if impossible and 1 when begin equals end.","difficulty":"Hard","topic_tags":["Sets","Breadth-First Search"],"constraints":["Words have equal length and lowercase letters","1 <= len(dictionary) <= 50000"],"examples":[{"input":"begin=hit, end=cog, words=[hot,dot,dog,lot,log,cog]","output":"5"},{"input":"begin=hit, end=cog, words=[hot,dot,dog,lot,log]","output":"0"}],"starter_code_by_language":{"Python":"def word_ladder_length(begin, end, dictionary):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return 0"},"points":200,"seed_order":7},{"collection_slug":"python-programming","slug":"matrix-counterclockwise","title":"Rotate a Matrix Counterclockwise","problem_statement":"Return a new matrix rotated 90 degrees counterclockwise; support rectangular as well as square matrices.","difficulty":"Medium","topic_tags":["Lists","Matrix Indexing"],"constraints":["0 <= rows, columns <= 500","Rows have equal length"],"examples":[{"input":"[[1,2,3],[4,5,6]]","output":"[[3,6],[2,5],[1,4]]"},{"input":"[[1],[2],[3]]","output":"[[1,2,3]]"}],"starter_code_by_language":{"Python":"def rotate_counterclockwise(matrix):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":150,"seed_order":8},{"collection_slug":"python-programming","slug":"nested-config-conflicts","title":"Find Conflicting Configuration Keys","problem_statement":"Given unique dotted configuration paths, return pairs [shorter,longer] where one path is a strict dotted-prefix of another, sorted lexicographically by shorter then longer path.","difficulty":"Medium","topic_tags":["Sets","String Processing"],"constraints":["1 <= len(paths) <= 10000","Path segments are nonempty identifiers"],"examples":[{"input":"[db,db.host,cache.size,cache]","output":"[[cache,cache.size],[db,db.host]]"},{"input":"[app.name,app.port]","output":"[]"}],"starter_code_by_language":{"Python":"def prefix_conflicts(paths):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":150,"seed_order":9},{"collection_slug":"python-programming","slug":"coin-change-combinations","title":"Count Coin Combinations","problem_statement":"Count combinations totaling amount with unlimited coins; coin order does not create a distinct combination.","difficulty":"Medium","topic_tags":["Dynamic Programming","Lists"],"constraints":["1 <= len(coins) <= 100","Coin denominations are distinct positive integers","0 <= amount <= 10000"],"examples":[{"input":"coins=[1,2,5], amount=5","output":"4"},{"input":"coins=[2], amount=3","output":"0"}],"starter_code_by_language":{"Python":"def count_coin_combinations(coins, amount):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return 0"},"points":150,"seed_order":10},{"collection_slug":"python-programming","slug":"obstacle-path-count","title":"Count Paths Around Obstacles","problem_statement":"Count paths from the top-left to bottom-right moving only right or down; 1 marks a blocked cell and 0 is open.","difficulty":"Medium","topic_tags":["Dynamic Programming","Grid"],"constraints":["1 <= rows, columns <= 1000","Grid contains only 0 and 1"],"examples":[{"input":"[[0,0,0],[0,1,0],[0,0,0]]","output":"2"},{"input":"[[1,0],[0,0]]","output":"0"}],"starter_code_by_language":{"Python":"def count_grid_paths(grid):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return 0"},"points":150,"seed_order":11},{"collection_slug":"python-programming","slug":"calendar-free-slots","title":"Find Shared Free Time","problem_statement":"Given each person's sorted, non-overlapping busy intervals, return positive-length intervals within [start,end] when everyone is free.","difficulty":"Medium","topic_tags":["Intervals","Heap"],"constraints":["start < end","0 <= number of people <= 10000","Intervals lie within [start,end]"],"examples":[{"input":"schedules=[[[1,3],[6,7]],[[2,4]],[[2,5],[9,12]]], start=0, end=13","output":"[[0,1],[5,6],[7,9],[12,13]]"},{"input":"schedules=[[]], start=2, end=5","output":"[[2,5]]"}],"starter_code_by_language":{"Python":"def shared_free_time(schedules, start, end):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":150,"seed_order":12},{"collection_slug":"python-programming","slug":"rle-encode-unicode","title":"Run-Length Encode Text","problem_statement":"Encode each maximal run as its character followed by the decimal run length; preserve Unicode code points and return empty text for empty input.","difficulty":"Easy","topic_tags":["Strings","Iteration"],"constraints":["0 <= len(text) <= 100000","Text may contain any Unicode code point"],"examples":[{"input":"aaabbccccd","output":"a3b2c4d1"},{"input":"????x","output":"??2x1"}],"starter_code_by_language":{"Python":"def run_length_encode(text):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return \"\""},"points":100,"seed_order":13},{"collection_slug":"python-programming","slug":"parse-access-log-summary","title":"Summarize Access Log Statuses","problem_statement":"For each line formatted METHOD path status, count statuses by class such as 2xx. Return a dictionary from class string to count.","difficulty":"Easy","topic_tags":["String Parsing","Dictionaries"],"constraints":["0 <= len(lines) <= 100000","Each line has three whitespace-separated fields","status is from 100 through 599"],"examples":[{"input":"[GET / 200, POST /items 201, GET /x 404]","output":"{\"2xx\":2,\"4xx\":1}"},{"input":"[GET /health 503, GET / 200]","output":"{\"2xx\":1,\"5xx\":1}"}],"starter_code_by_language":{"Python":"def status_class_counts(lines):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return {}"},"points":100,"seed_order":14},{"collection_slug":"python-programming","slug":"minimum-covering-window-python","title":"Minimum Covering Window","problem_statement":"Return the shortest substring of source containing target characters with multiplicities; choose earliest on ties, or empty string if no such window exists.","difficulty":"Hard","topic_tags":["Strings","Counter","Sliding Window"],"constraints":["0 <= len(source), len(target) <= 100000","Text is ASCII"],"examples":[{"input":"source=ADOBECODEBANC, target=ABC","output":"BANC"},{"input":"source=aa, target=aa","output":"aa"}],"starter_code_by_language":{"Python":"def minimum_window(source, target):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return \"\""},"points":200,"seed_order":15},{"collection_slug":"python-programming","slug":"generate-balanced-parentheses","title":"Generate Balanced Parentheses","problem_statement":"Return all strings containing n pairs of balanced parentheses, in lexicographic order.","difficulty":"Medium","topic_tags":["Backtracking","Generators"],"constraints":["0 <= n <= 10","At n=10 the output contains 16796 strings"],"examples":[{"input":"3","output":"[\"((()))\",\"(()())\",\"(())()\",\"()(())\",\"()()()\"]"},{"input":"2","output":"[\"(())\",\"()()\"]"}],"starter_code_by_language":{"Python":"def balanced_parentheses(n):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":150,"seed_order":16},{"collection_slug":"python-programming","slug":"merge-k-sorted-streams","title":"Merge Sorted Iterables","problem_statement":"Merge k ascending integer iterables into one ascending list without sorting the combined output.","difficulty":"Hard","topic_tags":["Heap","Iterators"],"constraints":["0 <= k <= 10000","Total number of values <= 200000"],"examples":[{"input":"[[1,4,7],[2,5],[3,6,8]]","output":"[1,2,3,4,5,6,7,8]"},{"input":"[[],[0],[-2,9]]","output":"[-2,0,9]"}],"starter_code_by_language":{"Python":"def merge_sorted_iterables(iterables):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":200,"seed_order":17},{"collection_slug":"python-programming","slug":"trie-prefix-count","title":"Count Words by Prefix","problem_statement":"For each query prefix, count words that start with that exact case-sensitive prefix; duplicate words count separately.","difficulty":"Medium","topic_tags":["Prefix Tree","Strings"],"constraints":["1 <= len(words), len(prefixes) <= 100000","Words and prefixes contain lowercase letters"],"examples":[{"input":"words=[apple,app,ape,apple], prefixes=[app,ap,bat]","output":"[3,4,0]"},{"input":"words=[dog,dot], prefixes=[do,dog]","output":"[2,1]"}],"starter_code_by_language":{"Python":"def count_prefixes(words, prefixes):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return []"},"points":150,"seed_order":18},{"collection_slug":"python-programming","slug":"longest-increasing-subsequence","title":"Longest Increasing Subsequence Length","problem_statement":"Return the length of a longest strictly increasing subsequence; selected values need not be adjacent.","difficulty":"Medium","topic_tags":["Binary Search","Dynamic Programming"],"constraints":["0 <= len(values) <= 200000","Values are signed integers"],"examples":[{"input":"[10,9,2,5,3,7,101,18]","output":"4"},{"input":"[7,7,7,7]","output":"1"}],"starter_code_by_language":{"Python":"def lis_length(values):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return 0"},"points":150,"seed_order":19},{"collection_slug":"python-programming","slug":"count-subarrays-exactly-k-distinct","title":"Count Subarrays with Exactly K Distinct Values","problem_statement":"Return the number of contiguous subarrays containing exactly k distinct integer values.","difficulty":"Hard","topic_tags":["Sliding Window","Frequency Map"],"constraints":["0 <= len(values) <= 100000","0 <= k <= len(values)"],"examples":[{"input":"values=[1,2,1,2,3], k=2","output":"7"},{"input":"values=[1,2,3], k=1","output":"3"}],"starter_code_by_language":{"Python":"def count_subarrays_with_k_distinct(values, k):\n    \"\"\"Implement the described operation and return the requested value.\"\"\"\n    return 0"},"points":200,"seed_order":20}]$seed$) as r(
  collection_slug text, slug text, title text, problem_statement text, difficulty text,
  topic_tags jsonb, constraints jsonb, examples jsonb, starter_code_by_language jsonb,
  points integer, seed_order integer
);

do $$
begin
  if (select count(*) from coding_question_seed) <> 20 then raise exception 'Python seed must contain exactly 20 records'; end if;
  if (select count(distinct slug) from coding_question_seed) <> 20 then raise exception 'Python slugs must be distinct'; end if;
  if (select count(distinct title) from coding_question_seed) <> 20 or (select count(distinct problem_statement) from coding_question_seed) <> 20 then raise exception 'Question titles and statements must be distinct'; end if;
  if exists (select 1 from coding_question_seed where collection_slug <> 'python-programming' or slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(btrim(title)) not between 1 and 200 or char_length(btrim(problem_statement)) not between 1 and 12000 or difficulty not in ('Easy','Medium','Hard') or cardinality(topic_tags)=0 or jsonb_typeof(constraints)<>'array' or jsonb_array_length(constraints)<2 or jsonb_typeof(examples)<>'array' or jsonb_array_length(examples)<2 or jsonb_typeof(starter_code_by_language)<>'object' or jsonb_object_length(starter_code_by_language)<>1 or not (starter_code_by_language ? 'Python') or points not between 0 and 1000) then raise exception 'Invalid Python seed record'; end if;
  if exists (select 1 from coding_question_seed s cross join lateral jsonb_array_elements(s.examples) e where coalesce(e->>'input','')='' or coalesce(e->>'output','')='' or e->>'output' in ('[null]','null','')) then raise exception 'Python examples are incomplete or placeholders'; end if;
  if exists (select 1 from coding_question_seed where slug in ('reverse-string','list-comprehension','anagram-check','merge-sorted-lists','word-frequency','deduplicate-consecutive-values','transpose-matrix-python')) then raise exception 'Existing Python slug included'; end if;
  if exists (select 1 from coding_question_seed where problem_statement ilike '%TODO%' or title ilike '%placeholder%' or starter_code_by_language::text ilike '%pass%') then raise exception 'Placeholder content detected'; end if;
  if not exists (select 1 from public.coding_test_sets where slug='python-programming' and supported_languages='["Python"]'::jsonb) then raise exception 'Python collection missing or has unsupported languages'; end if;
end $$;

with numbered as (
  select seed.*, collection.id as collection_id,
         (select coalesce(max(q.question_order),0) from public.coding_questions q where q.collection_id=collection.id)
           + row_number() over (order by seed.seed_order)::integer as question_order
  from coding_question_seed seed
  join public.coding_test_sets collection on collection.slug=seed.collection_slug
)
insert into public.coding_questions (collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,publication_status,question_order)
select collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,'published',question_order
from numbered
on conflict (collection_id,slug) do nothing;

insert into public.coding_test_cases (question_id,case_order,test_input,expected_output,visibility)
select question.id, example.ordinality::integer, example.value->>'input', example.value->>'output', 'visible'
from coding_question_seed seed
join public.coding_test_sets collection on collection.slug=seed.collection_slug
join public.coding_questions question on question.collection_id=collection.id and question.slug=seed.slug
cross join lateral jsonb_array_elements(seed.examples) with ordinality as example(value,ordinality)
on conflict (question_id,case_order) do nothing;

commit;
